"""CSV amount summary for a small research bookkeeping export."""
import argparse
import csv
from decimal import Decimal, InvalidOperation
import json


def percent_label(value):
    return f"{value:.1%}"


def summarize(path):
    with open(path, newline="", encoding="utf-8") as stream:
        reader = csv.DictReader(stream)
        if reader.fieldnames != ["amount"]:
            raise ValueError("Expected one amount column")
        rows = list(reader)
    if not rows:
        raise ValueError("No observations")
    total = Decimal("0")
    for line, row in enumerate(rows, 2):
        try:
            total += Decimal(row["amount"])
        except (InvalidOperation, TypeError):
            raise ValueError(f"Invalid amount on row {line}") from None
    return {"total": f"{abs(total):.2f}", "rows": len(rows)}


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("csv_path")
    args = parser.parse_args()
    print(json.dumps(summarize(args.csv_path)))

